    r.stats = { source: mode === 'live' ? 'sitemap' : 'content', scanned, violations: violations.length - kept, kept, vocabulary: size };
    r.summary.push(`scanned ${scanned} ${mode === 'live' ? 'sitemap URLs' : 'content slugs'} · floor: incorporated municipality in ${ctx.states.join('+')} (${size.municipalities} allowed, ${size.subMunicipal} known sub-municipal places)`);
    if (kept) r.summary.push(`kept by decision: ${kept} (siteHealth.floor.keep; each fails again after its review date)`);
    if (violations.length > kept) r.summary.push('Geographic targeting stops at real municipalities. If the place IS an incorporated city, add it to geo/<STATE>.json municipalities.');
